#!/usr/bin/env node
// Architecture gate: dependency-cruiser + ESLint, normalized by rule id.
// Usage: node scripts/check-arch.mjs [--json <file>] [--quiet]
import { execFile } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { relative, resolve } from 'node:path';
import { promisify } from 'node:util';
import { ESLint } from 'eslint';

const run = promisify(execFile);
const cwd = process.cwd();
const args = process.argv.slice(2);
const jsonOut = args.includes('--json') ? args[args.indexOf('--json') + 1] : null;
const quiet = args.includes('--quiet');

const RULE_TAG = /\[(R\d+)\]/;

async function runDependencyCruiser() {
  const started = performance.now();
  const bin = resolve(cwd, 'node_modules/.bin/depcruise');
  let stdout;
  try {
    ({ stdout } = await run(bin, ['src', '--config', '.dependency-cruiser.cjs', '--output-type', 'json'], {
      cwd,
      maxBuffer: 64 * 1024 * 1024,
    }));
  } catch (error) {
    if (!error.stdout) throw error;
    stdout = error.stdout;
  }
  const result = JSON.parse(stdout);
  const violations = result.summary.violations.map((v) => ({
    rule: v.rule.name.split('-')[0],
    tool: 'dependency-cruiser',
    check: v.rule.name,
    file: v.from,
    line: null,
    detail: v.cycle ? `cycle: ${[v.from, ...v.cycle.map((c) => c.name ?? c)].join(' → ')}` : `→ ${v.to}`,
  }));
  return { violations, ms: performance.now() - started };
}

async function runEslint() {
  const started = performance.now();
  const eslint = new ESLint({ cwd });
  const results = await eslint.lintFiles(['src']);
  const violations = [];
  for (const result of results) {
    for (const message of result.messages) {
      if (message.fatal) {
        violations.push({
          rule: 'PARSE',
          tool: 'eslint',
          check: 'parse-error',
          file: relative(cwd, result.filePath),
          line: message.line ?? null,
          detail: message.message,
        });
        continue;
      }
      const tag = RULE_TAG.exec(message.message);
      if (!tag) continue;
      violations.push({
        rule: tag[1],
        tool: 'eslint',
        check: message.ruleId,
        file: relative(cwd, result.filePath),
        line: message.line,
        detail: message.message.replace(/\s+/g, ' ').trim(),
      });
    }
  }
  return { violations, ms: performance.now() - started };
}

const started = performance.now();
const [depcruise, eslint] = await Promise.all([runDependencyCruiser(), runEslint()]);
const durationMs = performance.now() - started;
const violations = [...depcruise.violations, ...eslint.violations].sort(
  (a, b) => Number(a.rule.slice(1)) - Number(b.rule.slice(1)) || a.file.localeCompare(b.file),
);

if (jsonOut) {
  writeFileSync(
    jsonOut,
    JSON.stringify(
      {
        passed: violations.length === 0,
        durationMs: Math.round(durationMs),
        dependencyCruiserMs: Math.round(depcruise.ms),
        eslintMs: Math.round(eslint.ms),
        rulesFired: [...new Set(violations.map((v) => v.rule))].sort((a, b) => Number(a.slice(1)) - Number(b.slice(1))),
        violations,
      },
      null,
      2,
    ),
  );
}

if (!quiet) {
  if (violations.length === 0) {
    console.log('✔ architecture gate passed: no boundary violations');
  } else {
    console.log(`✖ architecture gate failed: ${violations.length} violation(s)\n`);
    let current = null;
    for (const v of violations) {
      if (v.rule !== current) {
        current = v.rule;
        console.log(`${v.rule}`);
      }
      const where = v.line ? `${v.file}:${v.line}` : v.file;
      console.log(`  [${v.tool}] ${where}  ${v.detail}`);
    }
  }
  console.log(
    `\ngate time: ${Math.round(durationMs)} ms (dependency-cruiser ${Math.round(depcruise.ms)} ms, eslint ${Math.round(eslint.ms)} ms, in parallel)`,
  );
}

process.exit(violations.length === 0 ? 0 : 1);
/** @type {import('dependency-cruiser').IConfiguration} */
const { contexts } = require('./context-map.json');

const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const contractsAllowedFor = (name) => {
  const ctx = contexts[name];
  const own = ctx.publishes ? [ctx.publishes] : [];
  const upstream = ctx.upstream.map((u) => contexts[u].publishes).filter(Boolean);
  return [...own, ...upstream];
};

const upstreamContractRules = Object.keys(contexts).map((name) => {
  const allowed = contractsAllowedFor(name);
  return {
    name: `R2-contracts-only-from-upstream:${name}`,
    comment: `[R2] ${name} may only depend on the published language of itself and its upstream contexts (${allowed.join(', ') || 'none'}).`,
    severity: 'error',
    from: { path: `^src/modules/${escape(name)}/` },
    to: {
      path: '^src/contracts/',
      ...(allowed.length > 0 ? { pathNot: `^src/contracts/(${allowed.map(escape).join('|')})$` } : {}),
    },
  };
});

module.exports = {
  forbidden: [
    {
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

model SchedulingAppointment {
  id               String   @id
  practitionerId   String
  requesterId      String
  requesterName    String
  requesterPhone   String
  startsAt         DateTime
  endsAt           DateTime
  status           String
  cancelReason     String?
  createdAt        DateTime @default(now())

  @@index([practitionerId, startsAt])
}

model FrontDeskVisit {
  id             String    @id
  appointmentId  String    @unique
  personId       String
  practitionerId String
  expectedAt     DateTime
  status         String
  checkedInAt    DateTime?
}

model ClinicalEncounter {
  id             String    @id
  appointmentId  String    @unique
  patientId      String
  practitionerId String
  status         String
  notes          String?
  diagnosisCodes String    @default("[]")
  procedureCodes String    @default("[]")
  arrivedAt      DateTime
  startedAt      DateTime?
  completedAt    DateTime?
}

model BillingInvoice {
  id         String               @id
  payerId    String
  sourceType String
  sourceId   String
  status     String
  totalCents Int
  issuedAt   DateTime
  lines      BillingInvoiceLine[]

  @@unique([sourceType, sourceId])
}

model BillingInvoiceLine {
  id          String         @id
  invoiceId   String
  code        String
  description String
  amountCents Int
  invoice     BillingInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)
}
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { ClinicalEvents, EncounterCompleted } from '@/contracts/clinical.events';
import { InvoicingService } from '../application/invoicing.service';

@Injectable()
export class ClinicalEventsListener {
  constructor(private readonly invoicing: InvoicingService) {}

  @OnEvent(ClinicalEvents.EncounterCompleted)
  async onEncounterCompleted(event: EncounterCompleted): Promise<void> {
    await this.invoicing.invoiceEncounter({
      encounterId: event.encounterId,
      payerId: event.personId,
      procedureCodes: event.procedureCodes,
    });
  }
}
import { BadRequestException, Controller, Get, NotFoundException, Query } from '@nestjs/common';
import { InvoicingService } from '../application/invoicing.service';
import type { Invoice, InvoiceSourceType } from '../domain/invoice';

@Controller('billing/invoices')
export class InvoicesController {
  constructor(private readonly invoicing: InvoicingService) {}

  @Get()
  async list(
    @Query('payerId') payerId?: string,
    @Query('sourceType') sourceType?: InvoiceSourceType,
    @Query('sourceId') sourceId?: string,
  ) {
    if (sourceType && sourceId) {
      const invoice = await this.invoicing.invoiceFor({ type: sourceType, id: sourceId });
      if (!invoice) {
        throw new NotFoundException(`No invoice for ${sourceType} ${sourceId}`);
      }
      return [toResponse(invoice)];
    }
    if (!payerId) {
      throw new BadRequestException('payerId or sourceType+sourceId is required');
    }
    return (await this.invoicing.invoicesOf(payerId)).map(toResponse);
  }
}

function toResponse(invoice: Invoice) {
  const s = invoice.toSnapshot();
  return {
    id: s.id,
    payerId: s.payerId,
    source: s.source,
    status: s.status,
    lines: s.lines,
    totalCents: invoice.totalCents,
    issuedAt: s.issuedAt.toISOString(),
  };
}
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { AppointmentNoShow, SchedulingEvents } from '@/contracts/scheduling.events';
import { InvoicingService } from '../application/invoicing.service';

@Injectable()
export class SchedulingEventsListener {
  constructor(private readonly invoicing: InvoicingService) {}

  @OnEvent(SchedulingEvents.AppointmentNoShow)
  async onAppointmentNoShow(event: AppointmentNoShow): Promise<void> {
    await this.invoicing.chargeNoShow({ appointmentId: event.appointmentId, payerId: event.personId });
  }
}
import { FixedClock } from '@/shared-kernel';
import { Invoice, InvoiceSource } from '../domain/invoice';
import { SourceAlreadyInvoicedError } from '../domain/invoice.errors';
import { InvoiceRepository } from '../domain/invoice.repository';
import { PriceList } from '../domain/price-list';
import { InvoicingService } from './invoicing.service';

class InMemoryInvoiceRepository extends InvoiceRepository {
  readonly items: Invoice[] = [];

  async existsForSource(source: InvoiceSource) {
